"""receipts evidence: out/receipts.json → after/evidence.yml, the sidecar the Atlas can keep.

Keyed by entry id, one item per claim that has a sentence (supported, contradicted, inferred).
It sits next to entities.yml as data/evidence.yml, so schema 1 and the frozen entry schema are
untouched: the Atlas loader reads only its own file list.
"""
import json

import yaml

from receipts.probes import ROOT

HEADER = """# Atlas Receipts evidence: the sentence on each organization's own page behind each claim.
# Generated by `python -m receipts evidence` (github.com/VJ-yadav/atlas-receipts). Do not edit by hand.
# status: supported = code found this exact sentence on the page and it matches the Atlas value;
#         contradicted = the page says something else (page_value); inferred = a model reading, NOT verified.
# A claim with no item here has no sentence yet (silent or refused).
"""
KEEP = ("supported", "contradicted", "inferred")


def build(receipts):
    by = {}
    for r in sorted(receipts, key=lambda r: r["key"]):
        if r["status"] not in KEEP or r["entry_id"].startswith("planted-"):
            continue
        item = {"claim": r["key"].split(":", 1)[1], "status": r["status"], "url": r["url"],
                "quote": r["quote"], "fetched_at": r["fetched_at"], "page_sha256": r["sha256"]}
        if r["status"] == "contradicted":
            item["page_value"] = r["page_value"]
        by.setdefault(r["entry_id"], []).append(item)
    return HEADER + yaml.safe_dump(by, sort_keys=True, allow_unicode=True, width=120)


def run():
    receipts = json.loads((ROOT / "out" / "receipts.json").read_text())
    text = build(receipts)
    out = ROOT / "after" / "evidence.yml"
    out.parent.mkdir(exist_ok=True)
    out.write_text(text)
    n = sum(r["status"] in KEEP for r in receipts)
    print(f"wrote {out.relative_to(ROOT)}: {n} claims with a sentence, {len(text) // 1024} KB")
    return out
